}

export function createPlaneGeometry(w, h, ws, hs) {
    return new THREE.PlaneGeometry(w || 1, h || 1, ws || 1, hs || 1);
}

// Displaced plane — vertices perturbed by noise
export function createDisplacedPlaneGeometry(w, h, ws, hs, amplitude, frequency) {
    const geo = createPlaneGeometry(w, h, ws, hs);
    const pos = geo.attributes.position;
    for (let i = 0; i < pos.count; i++) {
        const x = pos.getX(i);
        const y = pos.getY(i);
        const nz = fbm2D(x * frequency, y * frequency, 3, 0.5);
        pos.setZ(i, nz * amplitude);
    }
    geo.computeVertexNormals();
    return geo;
}

// Procedural alien geometries — retro-futuristic bug shapes
export function createAlienGeometry(type, scale, freq) {
    const s = scale || 1.0;
    switch (type) {
        case 'octopus': {
            const group = new THREE.Group();
            // Body
            const body = new THREE.SphereGeometry(0.5 * s, 8, 6);
            group.add(new THREE.Mesh(body));
            // Eyes
            const eyeGeo = new THREE.SphereGeometry(0.15 * s, 6, 6);
            const leftEye = new THREE.Mesh(eyeGeo);
            leftEye.position.set(-0.2 * s, 0.15 * s, 0.35 * s);
            group.add(leftEye);
            const rightEye = new THREE.Mesh(eyeGeo);
            rightEye.position.set(0.2 * s, 0.15 * s, 0.35 * s);
            group.add(rightEye);
            // Tentacles
            const tentGeo = new THREE.CylinderGeometry(0.05 * s, 0.08 * s, 0.6 * s, 4);
            for (let i = -2; i <= 2; i++) {
                const tent = new THREE.Mesh(tentGeo);
                tent.position.set(i * 0.15 * s, -0.5 * s, 0);
                tent.rotation.z = i * 0.15;
                group.add(tent);
            }
            // Merge into single geometry
            const merged = new THREE.BufferGeometry();
            const positions = [];
            const normals = [];
            const dummy = new THREE.Object3D();
            group.updateMatrixWorld(true);
            group.traverse(child => {
                if (child.isMesh && child.geometry) {
                    const geo = child.geometry;
                    const posAttr = geo.attributes.position;
                    const normAttr = geo.attributes.normal;
                    for (let i = 0; i < posAttr.count; i++) {
                        dummy.position.set(posAttr.getX(i), posAttr.getY(i), posAttr.getZ(i));
                        dummy.applyMatrix4(child.matrixWorld);
                        positions.push(dummy.position.x, dummy.position.y, dummy.position.z);
                        if (normAttr) {
                            const n = new THREE.Vector3(normAttr.getX(i), normAttr.getY(i), normAttr.getZ(i));
                            n.applyQuaternion(child.matrixWorld.decompose(new THREE.Quaternion()).quaternion || new THREE.Quaternion());
                            normals.push(n.x, n.y, n.z);
                        }
                    }
                }
            });
            merged.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
            if (normals.length) merged.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
            merged.computeVertexNormals();
            return merged;
        }
        case 'squid':
        case 'squid2': {
            const geo = new THREE.ConeGeometry(0.4 * s, 0.7 * s, 6);
            geo.rotateX(Math.PI);
            return geo;
        }
        case 'crab':
        case 'crab2': {
            const geo = new THREE.BoxGeometry(0.7 * s, 0.4 * s, 0.3 * s);
            return geo;
        }
        default: {
            return new THREE.SphereGeometry(0.4 * s, 8, 6);
        }
    }
}

// --- Scene Builders ---

// Starfield using InstancedMesh for performance
export function createStarfield(scene, count, spread) {
    const geo = createSphereGeometry(0.05, 4, 4);
    const mat = createEmissiveMaterial(0xffffff, 1.5);
    const mesh = new THREE.InstancedMesh(geo, mat, count);
    const dummy = new THREE.Object3D();
    const colors = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
        dummy.position.set(
            (Math.random() - 0.5) * spread,
            (Math.random() - 0.5) * spread * 0.5,
            -Math.random() * spread * 0.5
        );
        dummy.updateMatrix();
        mesh.setMatrixAt(i, dummy.matrix);
        const brightness = 0.5 + Math.random() * 0.5;
        const tint = Math.random();
        colors[i * 3] = brightness * (tint > 0.7 ? 1.0 : 0.8);
        colors[i * 3 + 1] = brightness * (tint > 0.5 ? 1.0 : 0.85);
        colors[i * 3 + 2] = brightness;
    }
    mesh.instanceColor = new THREE.InstancedBufferAttribute(colors, 3);
    scene.add(mesh);
    return { mesh, geometry: geo, material: mat };
}

// Retro-futuristic ground plane with emissive grid
export function createGroundPlane(scene, width, depth, gridDivisions) {
    const geo = createPlaneGeometry(width, depth, gridDivisions, gridDivisions);
    const gridTex = createGridTexture(512, 64, '#004444', '#050510');
    const mat = new THREE.MeshStandardMaterial({
        map: gridTex,
        roughness: 0.8,
        metalness: 0.2,
        emissive: new THREE.Color(0x001122),
        emissiveIntensity: 0.3,
        emissiveMap: gridTex,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.y = -8;
    scene.add(mesh);
    return { mesh, geometry: geo, material: mat, texture: gridTex };
}

// --- Disposal Helpers ---

export function disposeAsset(asset) {
    if (!asset) return;
    if (asset.geometry) asset.geometry.dispose();
    if (asset.material) {
        if (Array.isArray(asset.material)) {
            asset.material.forEach(m => m.dispose());
        } else {
            asset.material.dispose();
        }
    }
    if (asset.texture) asset.texture.dispose();
}

import * as THREE from 'three';
import { createStandardMaterial, createAlienGeometry } from '../../shared/graphics/ProceduralAssets.js';

const ALIEN_TYPES = [
  { name: 'octopus',  points: 30, color: 0x00ffff, emissive: 0x003333, geoScale: 1.0 },
  { name: 'squid',    points: 20, color: 0xff00ff, emissive: 0x330033, geoScale: 0.9 },
  { name: 'squid2',   points: 20, color: 0x9900ff, emissive: 0x220033, geoScale: 0.9 },
  { name: 'crab',     points: 10, color: 0x00ff00, emissive: 0x003300, geoScale: 1.1 },
  { name: 'crab2',    points: 10, color: 0x88ff00, emissive: 0x113300, geoScale: 1.1 },
];

const GRID_COLS = 11;
const GRID_ROWS = 5;
const SPACING_X = 1.8;
const SPACING_Y = 1.6;
const START_X = -(GRID_COLS - 1) * SPACING_X / 2;
const START_Y = 12;

export class Alien {
  constructor(row, col, wave) {
    this.row = row;
    this.col = col;
    this.alive = true;
    this.type = ALIEN_TYPES[row];
    this.points = this.type.points;
    this.wave = wave;

    const baseX = START_X + col * SPACING_X;
    const baseY = START_Y - row * SPACING_Y;
    this.homeX = baseX;
    this.homeY = baseY;
    this.x = baseX;
    this.y = baseY;

    this.mesh = null;
    this.material = null;
    this.geometry = null;
    this.animPhase = Math.random() * Math.PI * 2;
    this.animSpeed = 2.0 + row * 0.3;
  }

  buildMesh(wave) {
    const freq = 0.5 + wave * 0.1;
    this.geometry = createAlienGeometry(this.type.name, this.type.geoScale, freq);
    this.material = createStandardMaterial(
      this.type.color, 0.3, 0.7,
      this.type.emissive, 1.5
    );
    this.mesh = new Mesh(this.geometry, this.material);
    this.mesh.position.set(this.x, this.y, 0);
  }

  update(dt, gridOffsetX, gridOffsetY) {
    if (!this.alive) return;
    this.animPhase += dt * this.animSpeed;
    const breathe = 1.0 + 0.08 * Math.sin(this.animPhase);
    this.mesh.scale.set(breathe, 2.0 + 0.1 * Math.sin(this.animPhase * 1.3), breathe);
    this.mesh.position.x = this.homeX + gridOffsetX;
    this.mesh.position.y = this.homeY + gridOffsetY;
    this.x = this.mesh.position.x;
    this.y = this.mesh.position.y;
  }

  getBounds() {
    if (!this.alive) return null;
    const hw = 0.7;
    const hh = 0.5;
    return {
      minX: this.x - hw, maxX: this.x + hw,
      minY: this.y - hh, maxY: this.y + hh,
    };
  }

  destroy() {
    this.alive = false;
    if (this.mesh) {
      this.mesh.visible = false;
      this.mesh.position.set(0, -9999, 0);
    }
  }

  dispose() {
    if (this.geometry) { this.geometry.dispose(); this.geometry = null; }
    if (this.material) { this.material.dispose(); this.material = null; }
    if (this.mesh) { this.mesh.parent?.remove(this.mesh); this.mesh = null; }
  }
}

import * as THREE from 'three';
import { ObjectPool } from '../../shared/core/ObjectPool.js';
import { aabbVsAabb } from '../../shared/math/Collision.js';

const CELL_SIZE = 0.4;
const SHIELD_COLS = 13;
const SHIELD_ROWS = 7;
const SHIELD_POSITIONS = [-5, -1.67, 1.67, 5];

const SHIELD_PATTERN = [
    '.XX..........XX.',
    '.XXX........XXX.',
    '.XXXX......XXXX.',
    'XXXXXXXXXX.XXXXX',
    'XXXXXXXXXXXXXXXX',
    'XXXXXXXXXXXXXXXX',
    'XXXXXXXXXXXXXXXX',
];

export class Barrier {
    constructor(positionX) {
        this.positionX = positionX;
        this.cells = [];
        this.group = new THREE.Group();
        this._build();
    }

    _build() {
        const halfCols = SHIELD_COLS / 2;
        const halfRows = SHIELD_ROWS / 2;

        for (let row = 0; row < SHIELD_ROWS; row++) {
            for (let col = 0; col < SHIELD_COLS; col++) {
                const patternRow = SHIELD_PATTERN[row];
                if (!patternRow || patternRow[col] === '.') continue;

                const cell = {
                    active: true,
                    x: this.positionX + (col - halfCols) * CELL_SIZE,
                    y: -2 + (row - halfRows) * CELL_SIZE,
                    width: CELL_SIZE,
                    height: CELL_SIZE,
                    mesh: null,
                };

                const geo = new THREE.BoxGeometry(CELL_SIZE * 0.9, CELL_SIZE * 0.9, CELL_SIZE * 0.5);
                const mat = new THREE.MeshStandardMaterial({
                    color: 0x00ff88,
                    emissive: 0x00ff88,
                    emissiveIntensity: 0.3,
                    roughness: 0.5,
                    metalness: 0.2,
                });
                const mesh = new THREE.Mesh(geo, mat);
                mesh.position.set(cell.x, cell.y, 0);
                this.group.add(mesh);
                cell.mesh = mesh;
                this.cells.push(cell);
            }
        }
    }

    checkCollision(projX, projY, projHW, projHH) {
        const pBox = { minX: projX - projHW, maxX: projX + projHW, minY: projY - projHH, maxY: projY + projHH, minZ: -0.25, maxZ: 0.25 };
        for (const cell of this.cells) {
            if (!cell.active) continue;
            const cBox = { minX: cell.x - cell.width/2, maxX: cell.x + cell.width/2, minY: cell.y - cell.height/2, maxY: cell.y + cell.height/2, minZ: -0.25, maxZ: 0.25 };
            if (aabbVsAabb(pBox, cBox).hit) {
                this.destroyCell(cell);
                return true;
            }
        }
        return false;
    }

    destroyCell(cell) {
        cell.active = false;
        if (cell.mesh) {
            this.group.remove(cell.mesh);
            cell.mesh.geometry.dispose();
            cell.mesh.material.dispose();
            cell.mesh = null;
        }
    }

    getActiveCount() {
        return this.cells.filter(c => c.active).length;
    }

    isDestroyed() {
        return this.getActiveCount() === 0;
    }

    dispose() {
        for (const cell of this.cells) {
            if (cell.mesh) {
                cell.mesh.geometry.dispose();
                cell.mesh.material.dispose();
            }
        }
        this.group.traverse(child => {
            if (child.isMesh) {
                child.geometry.dispose();
                if (Array.isArray(child.material)) {
                    child.material.forEach(m => m.dispose());
                } else if (child.material) {
                    child.material.dispose();
                }
            }
        });
    }
}

import * as THREE from 'three';
import { ObjectPool } from '../../shared/core/ObjectPool.js';
import { createStandardMaterial, createEmissiveMaterial } from '../../shared/graphics/ProceduralAssets.js';

const UFO_SPAWN_INTERVAL_MIN = 15;
const UFO_SPAWN_INTERVAL_MAX = 30;
const UFO_SPEED = 4;
const UFO_Y = 12;
const UFO_POINTS = [50, 100, 150, 300];

export class UFO {
    constructor(scene, onScore, onDeath) {
        this.scene = scene;
        this.onScore = onScore;
        this.onDeath = onDeath;
        this.mesh = null;
        this.active = false;
        this.direction = 1;
        this.spawnTimer = 0;
        this.nextSpawn = this._randomInterval();
        this.points = UFO_POINTS[Math.floor(Math.random() * UFO_POINTS.length)];

        const geo = new THREE.CylinderGeometry(0.6, 0.9, 0.3, 12);
        const mat = createEmissiveMaterial(0xff2222, 2);
        this.mesh = new THREE.Mesh(geo, mat);
        this.mesh.visible = false;
        this.mesh.position.set(0, UFO_Y, 0);
        this.scene.add(this.mesh);

        // Dome on top
        const domeGeo = new THREE.SphereGeometry(0.5, 12, 8, 0, Math.PI * 2, 0, Math.PI / 2);
        const domeMat = createEmissiveMaterial(0xff4444, 1.5);
        this.dome = new THREE.Mesh(domeGeo, domeMat);
        this.dome.position.y = 0.15;
        this.mesh.add(this.dome);

        // Glow ring
        const ringGeo = new THREE.TorusGeometry(0.8, 0.05, 8, 24);
        const ringMat = createEmissiveMaterial(0xff0000, 3);
        this.ring = new THREE.Mesh(ringGeo, ringMat);
        this.ring.rotation.x = Math.PI / 2;
        this.mesh.add(this.ring);

        this._geo = geo;
        this._domeGeo = domeGeo;
        this._ringGeo = ringGeo;
        this._mat = mat;
        this._domeMat = domeMat;
        this._ringMat = ringMat;
    }

    _randomInterval() {
        return UFO_SPAWN_INTERVAL_MIN + Math.random() * (UFO_SPAWN_INTERVAL_MAX - UFO_SPAWN_INTERVAL_MIN);
    }

    update(dt, playerProjectiles, onHit) {
        if (!this.active) {
            this.spawnTimer += dt;
            if (this.spawnTimer >= this.nextSpawn) {
                this._spawn();
            }
            return;
        }

        // Move horizontally
        this.mesh.position.x += this.direction * UFO_SPEED * dt;

        // Rotate dome
        this.dome.rotation.y += 3 * dt;

        // Oscillate ring
        this.ring.scale.setScalar(1 + Math.sin(performance.now() * 0.01) * 0.1);

        // Check if off-screen
        if (Math.abs(this.mesh.position.x) > 14) {
            this._despawn();
        }

        // Check collision with player projectiles
        for (let i = playerProjectiles.length - 1; i >= 0; i--) {
            const proj = playerProjectiles[i];
            if (!proj.alive) continue;
            const dx = proj.mesh.position.x - this.mesh.position.x;
            const dy = proj.mesh.position.y - this.mesh.position.y;
            const dist = Math.sqrt(dx * dx + dy * dy);
            if (dist < 1.2) {
                this._destroy(proj, onHit);
                return;
            }
        }
    }

    _spawn() {
        this.active = true;
        this.direction = Math.random() < 0.5 ? -1 : 1;
        this.mesh.position.x = this.direction > 0 ? -14 : 14;
        this.mesh.position.y = UFO_Y;
        this.mesh.visible = true;
        this.spawnTimer = 0;
        this.nextSpawn = this._randomInterval();
    }

    _despawn() {
        this.active = false;
        this.mesh.visible = false;
        this.spawnTimer = 0;
        this.nextSpawn = this._randomInterval();
    }

    _destroy(projectile, onHit) {
        this.active = false;
        this.mesh.visible = false;
        this.onScore(this.points, this.mesh.position.clone());
        if (this.onDeath) {
            this.onDeath(this.mesh.position.clone());
        }
        if (projectile && onHit) {
            onHit(projectile, 'ufo');
        }
        this.spawnTimer = 0;
        this.nextSpawn = this._randomInterval();
    }

    dispose() {
        this.scene.remove(this.mesh);
        this._geo.dispose();
        this._domeGeo.dispose();
        this._ringGeo.dispose();
        this._mat.dispose();
        this._domeMat.dispose();
        this._ringMat.dispose();
    }
}

// Player entity for Space Invaders
import * as THREE from 'three';
import { vec2, vec2Copy, vec2Len } from '../../shared/math/VectorMath.js';
import { createStandardMaterial, createEmissiveMaterial } from '../../shared/graphics/ProceduralAssets.js';

export class Player {
    constructor(config) {
        this.position = vec2Copy([0, 0], config.position || [0, 0]);
        this.velocity = vec2(0, 0);
        this.moveSpeed = config.moveSpeed || 300;
        this.fireCooldown = 0;
        this.fireRate = config.fireRate || 0.25;
        this.lives = config.lives || 3;
        this.maxLives = this.lives;
        this.arenaBounds = config.arenaBounds || [-4, 4];
        this.alive = true;
        this.invincible = false;
        this.invincibleTimer = 0;
        this.invincibleDuration = 2.0;
        this.scale = config.scale || 1.0;
        this.blinkTimer = 0;
        this.blinkInterval = 0.1;

        // Create player ship geometry
        this.mesh = this._createShip();
        this.mesh.position.set(this.position[0], this.position[1], 0);
        this.mesh.scale.setScalar(this.scale);
    }

    _createShip() {
        const group = new THREE.Group();

        // Main body - triangular shape
        const bodyGeo = new THREE.ConeGeometry(0.4, 0.8, 4);
        const bodyMat = createStandardMaterial(0x00ffff, 0.3, 0.7);
        bodyMat.emissive = new THREE.Color(0x004444);
        bodyMat.emissiveIntensity = 0.5;
        const body = new THREE.Mesh(bodyGeo, bodyMat);
        body.rotation.y = Math.PI / 4;
        group.add(body);

        // Wings
        const wingGeo = new THREE.BoxGeometry(1.2, 0.1, 0.3);
        const wingMat = createStandardMaterial(0x00cccc, 0.4, 0.6);
        const wings = new THREE.Mesh(wingGeo, wingMat);
        wings.position.y = -0.2;
        group.add(wings);

        // Engine glow
        const engineGeo = new THREE.SphereGeometry(0.15, 8, 8);
        const engineMat = createEmissiveMaterial(0x00ffff, 2.0);
        const engine = new THREE.Mesh(engineGeo, engineMat);
        engine.position.y = -0.4;
        engine.name = 'engine';
        group.add(engine);

        return group;
    }

    update(dt, input) {
        if (!this.alive) return;

        // Handle invincibility
        if (this.invincible) {
            this.invincibleTimer -= dt;
            this.blinkTimer += dt;
            if (this.blinkTimer >= this.blinkInterval) {
                this.blinkTimer = 0;
                this.mesh.visible = !this.mesh.visible;
            }
            if (this.invincibleTimer <= 0) {
                this.invincible = false;
                this.mesh.visible = true;
            }
        }

        // Movement
        const moveX = input.getAxis('moveX');
        this.velocity[0] = moveX * this.moveSpeed;

        // Apply movement
        this.position[0] += this.velocity[0] * dt;

        // Clamp to arena bounds
        this.position[0] = Math.max(
            this.arenaBounds[0],
            Math.min(this.arenaBounds[1], this.position[0])
        );

        // Update mesh position
        this.mesh.position.x = this.position[0];
        this.mesh.position.y = this.position[1];

        // Engine glow intensity based on movement
        const engine = this.mesh.getObjectByName('engine');
        if (engine) {
            const intensity = 1.0 + Math.abs(moveX) * 2.0;
            engine.material.emissiveIntensity = intensity;
        }
    }

    canFire() {
        return this.fireCooldown <= 0 && this.alive;
    }

    fire() {
        if (!this.canFire()) return null;
        this.fireCooldown = this.fireRate;
        return {
            position: vec2.copy([this.position[0], this.position[1] + 0.5]),
            velocity: [0, 400],
            type: 'player'
        };
    }

    takeDamage() {
        if (this.invincible || !this.alive) return false;

        this.lives--;
        if (this.lives <= 0) {
            this.alive = false;
            this.mesh.visible = false;
            return true; // Player died
        }

        // Become invincible
        this.invincible = true;
        this.invincibleTimer = this.invincibleDuration;
        this.blinkTimer = 0;
        return false; // Player survived
    }

    reset() {
        this.lives = this.maxLives;
        this.alive = true;
        this.invincible = true;
        this.invincibleTimer = this.invincibleDuration;
        this.blinkTimer = 0;
        this.position[0] = 0;
        this.position[1] = 0;
        this.velocity[0] = 0;
        this.mesh.visible = true;
        this.mesh.position.set(0, 0, 0);
    }

    dispose() {
        this.mesh.traverse((child) => {
            if (child.isMesh) {
                child.geometry.dispose();
                if (child.material) {
                    child.material.dispose();
                }
            }
        });
    }
}

