    const breathe = 1.0 + 0.08 * Math.sin(this.animPhase);
    this.mesh.scale.set(breathe, 2.0 + 0.1 * Math.sin(this.animPhase * 1.3), breathe);
    this.mesh.position.x = this.homeX + gridOffsetX;
    this.mesh.position.y = this.homeY + gridOffsetY;
    this.x = this.mesh.position.x;
    this.y = this.mesh.position.y;
  }

  getBounds() {
    if (!this.alive) return null;
    const hw = 0.7;
    const hh = 0.5;
    return {
      minX: this.x - hw, maxX: this.x + hw,
      minY: this.y - hh, maxY: this.y + hh,
    };
  }

  destroy() {
    this.alive = false;
    if (this.mesh) {
      this.mesh.visible = false;
      this.mesh.position.set(0, -9999, 0);
    }
  }

  dispose() {
    if (this.geometry) { this.geometry.dispose(); this.geometry = null; }
    if (this.material) { this.material.dispose(); this.material = null; }
    if (this.mesh) { this.mesh.parent?.remove(this.mesh); this.mesh = null; }
  }
}

import * as THREE from 'three';
import { ObjectPool } from '../../shared/core/ObjectPool.js';
import { createStandardMaterial } from '../../shared/graphics/ProceduralAssets.js';

const BULLET_SPEED = 40;
const ALIEN_BULLET_SPEED = 18;
const BULLET_RADIUS = 0.25;

function createPlayerBullet() {
    const geo = new THREE.CylinderGeometry(0.08, 0.12, 0.8, 6);
    const mat = createStandardMaterial(0x00ffff, 0.2, 0.8, 0x00ffff, 2.0);
    const mesh = new THREE.Mesh(geo, mat);
    mesh.castShadow = false;
    return { mesh, speed: BULLET_SPEED, owner: 'player', alive: false };
}

function createAlienBullet() {
    const geo = new THREE.CylinderGeometry(0.06, 0.1, 0.6, 5);
    const mat = createStandardMaterial(0xff3366, 0.2, 0.8, 0xff3366, 2.0);
    const mesh = new THREE.Mesh(geo, mat);
    mesh.castShadow = false;
    return { mesh, speed: ALIEN_BULLET_SPEED, owner: 'alien', alive: false };
}

export class ProjectileManager {
    constructor() {
        this._playerPool = new ObjectPool(createPlayerBullet, (b) => {
            b.alive = false;
            b.mesh.visible = false;
        }, 120);
        this._alienPool = new ObjectPool(createAlienBullet, (b) => {
            b.alive = false;
            b.mesh.visible = false;
        }, 120);
        this._bullets = [];
        this._halfH = 12;
    }

    setBounds(halfH) { this._halfH = halfH; }

    spawnPlayerBullet(x, y) {
        const b = this._playerPool.acquire();
        if (!b) return null;
        b.alive = true;
        b.mesh.position.set(x, y, 0);
        b.mesh.visible = true;
        this._bullets.push(b);
        return b;
    }

    spawnAlienBullet(x, y) {
        const b = this._alienPool.acquire();
        if (!b) return null;
        b.alive = true;
        b.mesh.position.set(x, y, 0);
        b.mesh.visible = true;
        this._bullets.push(b);
        return b;
    }

    update(dt) {
        for (let i = this._bullets.length - 1; i >= 0; i--) {
            const b = this._bullets[i];
            if (!b.alive) continue;
            const dir = b.owner === 'player' ? 1 : -1;
            b.mesh.position.y += b.speed * dir * dt;
            if (b.mesh.position.y > this._halfH || b.mesh.position.y < -this._halfH) {
                this.release(b);
                this._bullets.splice(i, 1);
            }
        }
    }

    getAlive() {
        return this._bullets.filter(b => b.alive);
    }

    release(b) {
        b.alive = false;
        b.mesh.visible = false;
        const pool = b.owner === 'player' ? this._playerPool : this._alienPool;
        pool.release(b);
    }

    destroy() {
        for (const b of this._bullets) {
            b.mesh.geometry.dispose();
            b.mesh.material.dispose();
            const pool = b.owner === 'player' ? this._playerPool : this._alienPool;
            pool.release(b);
        }
        this._bullets.length = 0;
    }
}

import { Alien } from './Alien.js';

const GRID_COLS = 11;
const GRID_ROWS = 5;
const SPACING_X = 1.8;
const SPACING_Y = 1.6;
const START_X = -(GRID_COLS - 1) * SPACING_X / 2;
const START_Y = 12;

// Grid movement state
const DIR_RIGHT = 1;
const DIR_LEFT = -1;

export class AlienGrid {
    constructor(scene, wave = 1) {
        this.scene = scene;
        this.wave = wave;
        this.aliens = [];
        this.direction = DIR_RIGHT;
        this.offsetX = 0;
        this.offsetY = 0;
        this.stepDown = false;
        this.aliveCount = 0;
        this.totalCount = 0;

        // Movement parameters (scale with wave)
        this.moveSpeed = 8 + wave * 1.5;
        this.dropAmount = 1.2;
        this.fireCooldown = 0;
        this.fireRate = Math.max(0.3, 1.5 - wave * 0.1);

        // Build the grid
        this._build();
    }

    _build() {
        for (let row = 0; row < GRID_ROWS; row++) {
            for (let col = 0; col < GRID_COLS; col++) {
                const alien = new Alien(row, col, this.wave);
                alien.buildMesh(this.wave);
                this.scene.add(alien.mesh);
                this.aliens.push(alien);
                this.aliveCount++;
                this.totalCount++;
            }
        }
    }

    update(dt, projectiles, onAlienFire) {
        // Count alive aliens
        this.aliveCount = 0;
        for (const alien of this.aliens) {
            if (alien.alive) this.aliveCount++;
        }

        if (this.aliveCount <= 0) return false; // Grid wiped

        // Speed up as fewer aliens remain
        const speedMult = 1 + (this.totalCount - this.aliveCount) / this.totalCount * 2;
        const effectiveSpeed = this.moveSpeed * speedMult;

        // Move grid horizontally
        this.offsetX += this.direction * effectiveSpeed * dt;

        // Check bounds — if any alive alien would go off-screen, step down
        let needStep = false;
        for (const alien of this.aliens) {
            if (!alien.alive) continue;
            const worldX = alien.homeX + this.offsetX;
            if (worldX < -12 || worldX > 12) {
                needStep = true;
                break;
            }
        }

        if (needStep) {
            // Reverse direction and step down
            this.direction *= -1;
            this.offsetY -= this.dropAmount;
        }

        // Update each alien
        for (const alien of this.aliens) {
            alien.update(dt, this.offsetX, this.offsetY);
        }

        // Check if aliens reached player level
        for (const alien of this.aliens) {
            if (!alien.alive) continue;
            if (alien.y < -5) {
                return false; // Game over — aliens breached
            }
        }

        // Alien firing
        this.fireCooldown -= dt;
        if (this.fireCooldown <= 0 && this.aliveCount > 0) {
            this.fireCooldown = this.fireRate;
            this._fireRandom(onAlienFire);
        }

        return true; // Grid still active
    }

    _fireRandom(onAlienFire) {
        // Collect alive aliens
        const alive = this.aliens.filter(a => a.alive);
        if (alive.length === 0) return;

        // Pick a random alive alien to fire
        const shooter = alive[Math.floor(Math.random() * alive.length)];
        if (onAlienFire) {
            onAlienFire(shooter.x, shooter.y);
        }
    }

    checkProjectileHit(projX, projY) {
        // Returns the alien that was hit, or null
        for (const alien of this.aliens) {
            if (!alien.alive) continue;
            const bounds = alien.getBounds();
            if (!bounds) continue;
            if (projX >= bounds.minX && projX <= bounds.maxX &&
                projY >= bounds.minY && projY <= bounds.maxY) {
                alien.destroy();
                this.aliveCount--;
                return alien;
            }
        }
        return null;
    }

    isCleared() {
        return this.aliveCount <= 0;
    }

    dispose() {
        for (const alien of this.aliens) {
            alien.dispose();
        }
        this.aliens.length = 0;
    }
}

// Space_Invaders/Game.js — main game logic
import * as THREE from 'three';
import { Player } from './entities/Player.js';
import { AlienGrid } from './entities/AlienGrid.js';
import { ProjectileManager } from './entities/Projectile.js';
import { Barrier } from './entities/Barrier.js';
import { UFO } from './entities/UFO.js';
import { LevelGenerator } from './levels/LevelGenerator.js';
import { HUD } from './ui/HUD.js';
import { createStarfield, createGroundPlane } from '../../shared/graphics/ProceduralAssets.js';

const ARENA_HALF_W = 12;
const ARENA_HALF_H = 14;
const BARRIER_POSITIONS = [-5, -1.67, 1.67, 5];

export class Game {
    constructor(engine) {
        this.engine = engine;
        this.scene = engine.scene;
        this.camera = engine.camera;

        // Game state
        this.score = 0;
        this.wave = 1;
        this.state = 'MENU'; // MENU | PLAY | PAUSE | GAME_OVER | LEVEL_TRANSITION
        this.transitionTimer = 0;
        this.transitionDuration = 2.0;

        // Entities
        this.player = null;
        this.alienGrid = null;
        this.projectiles = null;
        this.barriers = [];
        this.ufo = null;

        // Scene decorations
        this.starfield = null;
        this.groundPlane = null;

        // Level config
        this.levelGen = new LevelGenerator();

        // HUD
        this.hud = null;

        // Input
        this.input = null;

        // Audio
        this.audio = null;

        // VFX
        this.particles = null;
        this.cameraShake = null;
        this.hitStop = null;
        this.shockwaves = null;
        this.floatingText = null;
        this.motionTrails = null;
    }

    init() {
        this.input = this.engine.input;
        this.audio = this.engine.audio;
        this.particles = this.engine.particleManager;
        this.cameraShake = this.engine.cameraShake;
        this.hitStop = this.engine.hitStop;
        this.shockwaves = this.engine.shockwaveRings;
        this.floatingText = this.engine.floatingText;
        this.motionTrails = this.engine.motionTrails;

        // Build scene
        this._buildScene();

        // Build HUD
        this.hud = new HUD();
        this.hud.showMenu();

        // Start in menu
        this.state = 'MENU';
    }

    _buildScene() {
        // Starfield
        this.starfield = createStarfield(this.scene, 500, 80);

        // Ground plane
        this.groundPlane = createGroundPlane(this.scene, 60, 40, 30);
    }

    _startGame() {
        this.score = 0;
        this.wave = 1;
        this._startWave();
        this.state = 'PLAY';
        this.hud.showGame();
        this.hud.updateScore(this.score);
        this.hud.updateLives(3);
        this.hud.updateWave(this.wave);
        this.audio?.playSFX('menu');
    }

    _startWave() {
        // Clean up previous wave
        if (this.alienGrid) this.alienGrid.dispose();
        this.barriers.forEach(b => { this.scene.remove(b.group); b.dispose(); });
        this.barriers = [];

        // Get level config
        const config = this.levelGen.generate(this.wave);

        // Create player
        this.player = new Player({
            position: [0, -8],
            moveSpeed: config.playerSpeed || 300,
            fireRate: config.fireRate || 0.25,
            lives: this.player ? this.player.lives : 3,
            arenaBounds: [-ARENA_HALF_W, ARENA_HALF_W],
        });
        this.scene.add(this.player.mesh);

        // Register player for motion trails
        if (this.motionTrails) {
            this.motionTrails.register(this.player, 8, 0x00ffff, 0.15, 0.2);
        }

        // Create alien grid
        this.alienGrid = new AlienGrid(this.scene, this.wave);

        // Create projectile manager
        this.projectiles = new ProjectileManager();
        this.projectiles.setBounds(ARENA_HALF_H);

        // Create barriers
        for (const bx of BARRIER_POSITIONS) {
            const barrier = new Barrier(bx);
            this.scene.add(barrier.group);
            this.barriers.push(barrier);
        }

        // Create UFO
        this.ufo = new UFO(this.scene,
            (pts, pos) => this._onUFOHit(pts, pos),
            (pos) => this._onUFODeath(pos)
        );

        this.hud.updateWave(this.wave);
    }

    _onUFOHit(pts, pos) {
        this.score += pts;
        this.hud.updateScore(this.score);
        this.audio?.playSFX('ufoDeath');
        this.audio?.playSFX('score');
        this._spawnExplosion(pos.x, pos.y, 0xff2222, 30);
        this.cameraShake?.shake(2, 0.3);
        this.floatingText?.spawn(new THREE.Vector3(pos.x, pos.y, 0), `+${pts}`, '#ff4444');
    }

    _onUFODeath(pos) {
        this._spawnExplosion(pos.x, pos.y, 0xff0000, 40);
        this.shockwaves?.emit(new THREE.Vector3(pos.x, pos.y, 0), 5, 0xff0000, 0.8);
    }

    _spawnExplosion(x, y, color, count) {
        if (!this.particles) return;
        this.particles.burst(
            new THREE.Vector3(x, y, 0),
            count, 0.5,
            typeof color === 'string' ? color : new THREE.Color(color),
            8, 1.0, -2, 2
        );
    }

    update(dt, engine) {
        if (this.state === 'MENU') {
            this._updateMenu(dt);
            return;
        }

        if (this.state === 'GAME_OVER') {
            this._updateGameOver(dt);
            return;
        }

        if (this.state === 'PAUSE') {
            this._updatePause(dt);
            return;
        }

        if (this.state === 'LEVEL_TRANSITION') {
            this._updateTransition(dt);
            return;
        }

        // --- PLAY state ---
        this._updatePlay(dt);
    }

    _updateMenu(dt) {
        if (this.input && this.input.isJustPressed('confirm')) {
            this._startGame();
        }
    }

    _updatePause(dt) {
        if (this.input && this.input.isJustPressed('pause')) {
            this.state = 'PLAY';
            this.hud.showGame();
        }
    }

    _updateGameOver(dt) {
        if (this.input && this.input.isJustPressed('confirm')) {
            this._startGame();
        }
    }

    _updateTransition(dt) {
        this.transitionTimer -= dt;
        if (this.transitionTimer <= 0) {
            this.state = 'PLAY';
            this.hud.showGame();
        }
    }

    _updatePlay(dt) {
        // Pause toggle
        if (this.input && this.input.isJustPressed('pause')) {
            this.state = 'PAUSE';
            this.hud.showPause();
            return;
        }

        // Update player
        this.player.fireCooldown -= dt;
        this.player.update(dt, this.input);

        // Player fire
        if (this.input && this.input.isJustPressed('fire') && this.player.canFire()) {
            const bullet = this.player.fire();
            if (bullet) {
                this.projectiles.spawnPlayerBullet(bullet.position[0], bullet.position[1]);
                this.audio?.playSFX('shoot');
            }
        }

        // Update projectiles
        this.projectiles.update(dt);

        // Update alien grid
        const gridActive = this.alienGrid.update(dt, this.projectiles, (x, y) => {
            this.projectiles.spawnAlienBullet(x, y);
            this.audio?.playSFX('alienShoot');
        });

        // Check projectile vs alien collisions
        const aliveBullets = this.projectiles.getAlive();
        for (let i = aliveBullets.length - 1; i >= 0; i--) {
            const b = aliveBullets[i];
            if (!b.alive || b.owner !== 'player') continue;

            // Check vs aliens
            const hit = this.alienGrid.checkProjectileHit(b.mesh.position.x, b.mesh.position.y);
            if (hit) {
                this.score += hit.points;
                this.hud.updateScore(this.score);
                this._spawnExplosion(hit.x, hit.y, hit.type.color, 15);
                this.shockwaves?.emit(new THREE.Vector3(hit.x, hit.y, 0), 3, hit.type.color, 0.5);
                this.cameraShake?.shake(0.5, 0.15);
                this.floatingText?.spawn(new THREE.Vector3(hit.x, hit.y, 0), `+${hit.points}`, '#00ff00');
                this.audio?.playSFX('alienDeath');
                this.projectiles.release(b);
                continue;
            }

            // Check vs barriers
            let barrierHit = false;
            for (const barrier of this.barriers) {
                if (barrier.checkCollision(b.mesh.position.x, b.mesh.position.y, 0.15, 0.4)) {
                    this._spawnExplosion(b.mesh.position.x, b.mesh.position.y, 0x00ff88, 5);
                    this.projectiles.release(b);
                    barrierHit = true;
                    break;
                }
            }
            if (barrierHit) continue;
        }

        // Check alien bullets vs player
        for (let i = aliveBullets.length - 1; i >= 0; i--) {
            const b = aliveBullets[i];
            if (!b.alive || b.owner !== 'alien') continue;

            // Check vs player
            const dx = b.mesh.position.x - this.player.position[0];
            const dy = b.mesh.position.y - this.player.position[1];
            if (Math.sqrt(dx * dx + dy * dy) < 0.6) {
                const died = this.player.takeDamage();
                this._spawnExplosion(this.player.position[0], this.player.position[1], 0x00ffff, 20);
                this.cameraShake?.shake(1.5, 0.3);
                this.hitStop?.trigger(100);
                this.audio?.playSFX('playerHit');
                this.projectiles.release(b);
                this.hud.updateLives(this.player.lives);

                if (died) {
                    this.audio?.playSFX('gameOver');
                    this.state = 'GAME_OVER';
                    this.hud.showGameOver(this.score);
                }
                continue;
            }

            // Check vs barriers
            for (const barrier of this.barriers) {
                if (barrier.checkCollision(b.mesh.position.x, b.mesh.position.y, 0.12, 0.3)) {
                    this._spawnExplosion(b.mesh.position.x, b.mesh.position.y, 0x00ff88, 5);
                    this.projectiles.release(b);
                    break;
                }
            }
        }

        // Check alien vs player collision
        for (const alien of this.alienGrid.aliens) {
            if (!alien.alive) continue;
            const dx = alien.x - this.player.position[0];
            const dy = alien.y - this.player.position[1];
            if (Math.sqrt(dx * dx + dy * dy) < 1.0) {
                const died = this.player.takeDamage();
                this._spawnExplosion(this.player.position[0], this.player.position[1], 0x00ffff, 25);
                this.cameraShake?.shake(2, 0.4);
                this.hitStop?.trigger(150);
                this.audio?.playSFX('playerHit');
                this.hud.updateLives(this.player.lives);

                if (died) {
                    this.audio?.playSFX('gameOver');
                    this.state = 'GAME_OVER';
                    this.hud.showGameOver(this.score);
                }
                break;
            }
        }

        // Update UFO
        this.ufo.update(dt, this.projectiles.getAlive(), (proj, target) => {
            this.projectiles.release(proj);
        });

        // Check if wave cleared
        if (this.alienGrid.isCleared()) {
            this.audio?.playSFX('waveComplete');
            this.wave++;
            this.transitionTimer = this.transitionDuration;
            this.state = 'LEVEL_TRANSITION';
            this.hud.showLevelTransition(this.wave);
        }
    }

    dispose() {
        if (this.player) this.player.dispose();
        if (this.alienGrid) this.alienGrid.dispose();
        if (this.projectiles) this.projectiles.destroy();
        if (this.ufo) this.ufo.dispose();
        this.barriers.forEach(b => { this.scene.remove(b.group); b.dispose(); });
        this.barriers = [];
        if (this.starfield) {
            this.starfield.mesh.geometry.dispose();
            this.starfield.mesh.material.dispose();
            this.scene.remove(this.starfield.mesh);
        }
        if (this.groundPlane) {
            this.groundPlane.mesh.geometry.dispose();
            this.groundPlane.mesh.material.dispose();
            this.groundPlane.texture?.dispose();
            this.scene.remove(this.groundPlane.mesh);
        }
        if (this.hud) this.hud.dispose();
    }
}

